INSERT INTO `bots` (`idBot`, `botNombre`, `botDescripcion`, `botValor`, `botPorcentaje`, `botEstado`) VALUES
(1, 'Bot de Apuestas Automatizadas', 'El bot de apuestas deportivas de Surebets24/7.com es una herramienta completa que combina análisis estadístico, evaluación contextual y ejecución automatizada de apuestas. Utiliza tecnología de inteligencia artificial para ofrecer a los usuarios la información más precisa y tomar decisiones estratégicas en tiempo real. Con acceso a una amplia gama de eventos deportivos, este bot proporciona una ventaja competitiva para maximizar las ganancias en las apuestas deportivas.', '3000', '30', 'ACTIVO');
